/* 17 insight cards */
.ins-head{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}
.ins-head .t{font-weight:600;font-size:14px}
.pager{margin-left:auto;display:flex;align-items:center;gap:6px}
.pager button{width:28px;height:28px;display:grid;place-items:center;border:1px solid var(--line);color:var(--muted);transition:color .25s,border-color .25s}
.pager button:hover{color:var(--text);border-color:var(--icon-line)}
.ins-body{padding:16px;transition:opacity .25s ease,transform .3s var(--ease)}
.ins-body.out{opacity:0;transform:translateY(4px)}
.ins-text{font-size:15px;line-height:1.6}
.ins-text code{font-family:var(--mono);font-size:13px;padding:0 5px;background:var(--chip)}
.ins-text code.bad{color:var(--danger);background:rgba(255,90,95,.08)}
.ins-text code.good{color:var(--success);background:rgba(62,207,142,.08)}
.chart{position:relative;margin-top:16px;border:1px solid var(--line);height:130px;cursor:crosshair;touch-action:none}
.chart svg{position:absolute;inset:0;width:100%;height:100%}
.chart .ln{fill:none;stroke:var(--accent);stroke-width:1.5;vector-effect:non-scaling-stroke}
.chart .grid-l{stroke:var(--line);stroke-width:1;vector-effect:non-scaling-stroke}
.scrub{position:absolute;top:0;bottom:0;width:1px;background:var(--icon-line);opacity:0;transition:opacity .2s;pointer-events:none}
.scrub-dot{position:absolute;width:7px;height:7px;background:var(--accent);box-shadow:0 0 0 4px var(--bg-deep);transform:translate(-50%,-50%);opacity:0;transition:opacity .2s;pointer-events:none}
.scrub-tip{position:absolute;top:8px;padding:3px 8px;background:var(--panel);border:1px solid var(--icon-line);font-family:var(--mono);font-weight:700;font-size:11px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none}
.chart.active .scrub,.chart.active .scrub-dot,.chart.active .scrub-tip{opacity:1}
.ins-acts{display:flex;gap:8px;padding:0 16px 16px}
.ins-acts .btn{padding:8px 14px;font-size:13px}

/* insight text: mentions and values sit at the same size as the sentence */
.ins-text code,.ins-text .mention{font-family:inherit;font-size:inherit;font-weight:600;line-height:inherit;padding:0 5px;vertical-align:baseline}
html:not([data-style="soft"]) .ins-text code,html:not([data-style="soft"]) .ins-text .mention{font-family:var(--mono);font-size:.9em}

/* ---------- 17 insight cards ---------- */
{
  const pages = [
    { text:'Design reviews in <span class="mention">@Product team</span> take <code>2.4 days</code> on average, up <code class="bad">+18%</code> since last month.', d:[1.6,1.7,1.9,1.8,2.0,2.2,2.1,2.4], u:' days' },
    { text:'Handoff questions dropped to <code>6 per sprint</code>, down <code class="good">-40%</code> after the new spec template.', d:[11,10,10,9,8,7,7,6], u:' questions' },
    { text:'<span class="mention">@Web team</span> shipped <code>14 pages</code> this sprint, the most in eight weeks.', d:[8,9,7,10,11,9,12,14], u:' pages' }
  ];
  let p = 0, pts = [];
  const body = $('#ins-body'), chart = $('#ins-chart');
  function draw(){
    const d = pages[p].d, mn = Math.min(...d), mx = Math.max(...d), W = 400, H = 130, pad = 16;
    pts = d.map((v, i) => [i / (d.length - 1) * W, H - pad - (v - mn) / (mx - mn || 1) * (H - pad * 2)]);
    let path = `M${pts[0][0]},${pts[0][1]}`;
    for (let i = 1; i < pts.length; i++){ const [x0, y0] = pts[i-1], [x1, y1] = pts[i], cx = (x0 + x1) / 2; path += ` C${cx},${y0} ${cx},${y1} ${x1},${y1}`; }
    $('#ins-line').setAttribute('d', path); $('#ins-area').setAttribute('d', path + ` L${W},${H} L0,${H} Z`);
    $('#ins-text').innerHTML = pages[p].text; $('#ins-page').textContent = (p + 1) + ' / ' + pages.length;
  }
  function go(n){ p = (p + n + pages.length) % pages.length; Sound.play('tab'); body.classList.add('out'); setTimeout(() => { draw(); body.classList.remove('out'); }, 250); }
  $('#ins-prev').addEventListener('click', () => go(-1)); $('#ins-next').addEventListener('click', () => go(1));
  let lastI = -1;
  function scrub(e){
    const r = chart.getBoundingClientRect(), x = Math.max(0, Math.min(r.width, e.clientX - r.left));
    const i = Math.round(x / r.width * (pts.length - 1)), px = pts[i][0] / 400 * r.width, py = pts[i][1] / 130 * r.height;
    chart.classList.add('active');
    $('#ins-scrub').style.left = px + 'px'; const dot = $('#ins-dot'); dot.style.left = px + 'px'; dot.style.top = py + 'px';
    const tip = $('#ins-tip'); tip.textContent = 'Week ' + (i + 1) + ', ' + pages[p].d[i] + pages[p].u;
    tip.style.left = Math.min(r.width - tip.offsetWidth - 6, Math.max(6, px - tip.offsetWidth / 2)) + 'px';
    if (i !== lastI){ lastI = i; Sound.play('stream'); }
  }
  chart.addEventListener('pointermove', scrub); chart.addEventListener('pointerdown', scrub);
  chart.addEventListener('pointerleave', () => { chart.classList.remove('active'); lastI = -1; });
  draw();
}
